mapper.select:
select u.user_id as user_id, u.full_name as full_name, u.email as email, u.phone as phone,
c.dob as dob, c.address as address
from users u left join customer c on c.user_id = u.user_id where u.user_id = #{userId}

mapper.update:
UPDATE users
email = #{email}, phone = #{phone},
WHERE user_id = #{userId}
